namespace Erdos291Fragment

def L (n : Nat) : Nat :=
  (Finset.Icc 1 n).lcm (fun x => x)

def a (n : Nat) : Nat :=
  ∑ k ∈ Finset.Icc 1 n, L n / k

def harmonicNumerator (k : Nat) : Int :=
  (∑ i ∈ Finset.Icc 1 k, (1 : Rat) / i).num

def check_L1_3_3 : Bool :=
  decide (3 ∣ Nat.gcd (a 3) (L 3) ↔
    (3 : Int) ∣ harmonicNumerator (3 / 3 ^ Nat.log 3 3))

end Erdos291Fragment

